// Allocation and Type Casting
int size = 10;
int* data_ptr = (int*)malloc(sizeof(int) * size);

if (data_ptr != NULL) {
    // Pointer dereferencing and indexing
    *data_ptr = 100;
    data_ptr[1] = 101;

    // Pointer arithmetic (moves the address)
    int third_val = *(data_ptr + 2);

    // Reallocation (changing size)
    data_ptr = (int*)realloc(data_ptr, sizeof(int) * 20);

    // Deallocation
    free(data_ptr);
    data_ptr = NULL;
}
